CREATE TABLE questions (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, question TEXT NOT NULL, public_question TEXT NOT NULL, answer TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','answered','published')), created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, ip_hash TEXT NOT NULL, deleted_at BIGINT);
CREATE INDEX questions_status_idx ON questions (status,deleted_at,created_at);
CREATE INDEX questions_ip_idx ON questions (ip_hash,created_at);
CREATE INDEX questions_email_idx ON questions (email,created_at);

INSERT INTO questions (id,name,email,question,public_question,answer,status,created_at,updated_at,ip_hash) VALUES ('00000000-0000-4000-8000-000000000001','Editorial FAQ','','Where should I start?','Where should I start?','Start with your subject interests, preferred qualification, and a realistic budget. Then compare destinations and check entry requirements directly with universities.','published',1795640500000,1795640500000,'editorial');
INSERT INTO questions (id,name,email,question,public_question,answer,status,created_at,updated_at,ip_hash) VALUES ('00000000-0000-4000-8000-000000000002','Editorial FAQ','','Can I apply for a scholarship?','Can I apply for a scholarship?','Many universities offer scholarships, but availability and eligibility vary. Check each university’s official funding pages and apply before the relevant deadline.','published',1795640500001,1795640500001,'editorial');
INSERT INTO questions (id,name,email,question,public_question,answer,status,created_at,updated_at,ip_hash) VALUES ('00000000-0000-4000-8000-000000000003','Editorial FAQ','','What documents will I need?','What documents will I need?','Common requirements include academic transcripts, a passport, a personal statement, references, and evidence of language proficiency. Your chosen institution will confirm its exact list.','published',1795640500002,1795640500002,'editorial');
INSERT INTO questions (id,name,email,question,public_question,answer,status,created_at,updated_at,ip_hash) VALUES ('00000000-0000-4000-8000-000000000004','Editorial FAQ','','When should I begin my application?','When should I begin my application?','Aim to begin researching 9–12 months before your preferred intake. Application and visa timelines vary by institution and destination.','published',1795640500003,1795640500003,'editorial');
